     * @return True if the authorization has been used
     */
    function authorizationState(address authorizer, bytes32 nonce) external view returns (bool) {
        return _authorizationStates[authorizer][nonce];
    }

    /**
     * @dev Execute a transfer with an authorization signature (EIP-7598)
     * @param from Payer's address (Authorizer)
     * @param to Payee's address
     * @param value Amount to transfer
     * @param validAfter The time after which this is valid (unix time)
     * @param validBefore The time before which this is valid (unix time)
     * @param nonce Unique nonce for this authorization
     * @param signature Signature bytes (EOA signature or EIP-1271 contract signature)
     */
    function _transferOrReceiveWithAuthorization(
        bytes32 typeHash,
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes memory signature
    ) internal {
        // Validate time window
        require(block.timestamp > validAfter, "Authorization not yet valid");
        require(block.timestamp < validBefore, "Authorization expired");

        // Validate nonce
        require(!_authorizationStates[from][nonce], "Authorization already used");

        // Build EIP-712 struct hash
        bytes32 structHash = keccak256(
            abi.encode(
                typeHash,
                from,
                to,
                value,
                validAfter,
                validBefore,
                nonce
            )
        );

        // Build EIP-712 digest
        bytes32 digest = _hashTypedDataV4(structHash);

        // Validate signature (supports both EOA and EIP-1271 smart contracts)
        require(
            SignatureCheckerUpgradeable.isValidSignatureNow(from, digest, signature),
            "Invalid signature"
        );

        // Mark authorization as used
        _authorizationStates[from][nonce] = true;
        emit AuthorizationUsed(from, nonce);

        // Execute the transfer
        _transfer(from, to, value);
    }

    /**
     * @dev Cancel an authorization before it's used
     * @param authorizer Address that provided the authorization (must be msg.sender)
     * @param nonce Nonce of the authorization to cancel
     */
    function cancelAuthorization(address authorizer, bytes32 nonce) external {
        require(msg.sender == authorizer, "Caller must be the authorizer");
        require(!_authorizationStates[authorizer][nonce], "Authorization already used");

        _authorizationStates[authorizer][nonce] = true;
        emit AuthorizationCanceled(authorizer, nonce);
    }

    /**
     * @dev Gap for future upgrades
     * 
     * Storage Layout for StablecoinV2:
     * - Slot 359: _authorizationStates (mapping)
     * - Slot 360: eip7598EnableFlag (bool)
     * - Slot 361-408: __gap (48 slots)
     * 
     * Total new slots used: 2
     * Gap size: 48 (50 - 2 = 48)
     * 
     * IMPORTANT: When adding new state variables in future upgrades (V3, V4, etc.):
     * 1. Add new variables BEFORE this __gap
     * 2. Reduce __gap size by the number of new slots used
     * 3. Verify storage layout with `forge inspect StablecoinV3 storage-layout`
     */
    uint256[48] private __gap;
}"},"dependencyManifest":{"sourceUnits":["lib/openzeppelin-contracts-upgradeable/contracts/access/Ownable2StepUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/access/OwnableUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/interfaces/IERC1271Upgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/proxy/utils/Initializable.sol","lib/openzeppelin-contracts-upgradeable/contracts/security/PausableUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/ERC20Upgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/extensions/draft-ERC20PermitUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/extensions/draft-IERC20PermitUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/extensions/IERC20MetadataUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/token/ERC20/IERC20Upgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/AddressUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/ContextUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/CountersUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/cryptography/ECDSAUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/cryptography/EIP712Upgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/cryptography/SignatureCheckerUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/math/MathUpgradeable.sol","lib/openzeppelin-contracts-upgradeable/contracts/utils/StringsUpgradeable.sol"],"reviewBoundary":"Dependency source contents are covered by compilation/static analysis, not supplied to the ordinary LLM."},"localSlitherEvidence":{"version":1,"experimentId":"full-due-diligence","workflow":"ordinary-local-slither-baseline-candidate","status":"measured","settlement":{"status":"not-paid","reason":"Local static analysis only."},"inputBundleHash":